on conflict (id) do update set
  name = excluded.name,
  country = excluded.country,
  city = excluded.city,
  neighborhood = excluded.neighborhood,
  coordinates = excluded.coordinates,
  photo = coalesce(public.editorial_pois.photo, excluded.photo),
  guide_ids = excluded.guide_ids,
  guide_slugs = excluded.guide_slugs,
  categories = excluded.categories;

insert into public.editorial_guides (
  id,
  slug,
  category,
  country,
  city,
  neighborhood,
  list
)
values
  ('list-madrid-sol-centro-restaurants', 'madrid-sol-centro-restaurants', 'Food', 'Spain', 'Madrid', 'Sol & Centro', '{"id":"list-madrid-sol-centro-restaurants","slug":"madrid-sol-centro-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Sol and Centro, Madrid","seoDescription":"Best restaurants in Sol and Centro, Madrid, for historic dining rooms, tapas counters, market halls, churros, and central old-Madrid meals.","title":"Kilometer-Zero Classics and Counters","description":"Sol and Centro need restaurants that survive the tourist pressure: old dining rooms, market snacks, fried-cod counters, and sweet stops that make sense between Plaza Mayor, Gran Via, and the Royal Palace.","url":"https://www.google.com/maps/search/sol+centro+madrid+restaurants","category":"Food","location":{"city":"Madrid","neighborhood":"Sol & Centro","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"sol-food-lhardy","name":"Lhardy","coordinates":[40.4172,-3.7003],"description":"Lhardy earns its spot in the Sol & Centro food guide because it fills a clear meal role for this route. Historic old-Madrid dining room for a formal central meal, croquetas, consomme, and a sense of Sol before it became only a pass-through zone. Use it when the meal should be a reservation anchor rather than a casual crawl stop.","price":"$$","priceSource":"The Infatuation / Google Maps","hours":{"mon":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","tue":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","wed":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","thu":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","fri":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sat":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sun":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM"},"photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-madrid-lhardy"},{"id":"sol-food-casa-labra","name":"Casa Labra","coordinates":[40.4172,-3.7044],"description":"Casa Labra earns its spot in the Sol & Centro food guide because it fills a clear meal role for this route. Standing-room cod, croquettes, beer, and quick service make Casa Labra the useful counter stop near Puerta del Sol. Use it when you want a compact local-feeling stop that can sit before drinks or sightseeing.","price":"$","priceSource":"Time Out / Google Maps","hours":{"mon":"12:00 PM-11:00 PM","tue":"12:00 PM-11:00 PM","wed":"12:00 PM-11:00 PM","thu":"12:00 PM-11:30 PM","fri":"12:00 PM-12:00 AM","sat":"12:00 PM-12:00 AM","sun":"12:00 PM-10:30 PM"},"photo":"https://images.unsplash.com/photo-1515443961218-a51367888e4b?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-madrid-casa-labra"},{"id":"sol-food-mercado-san-miguel","name":"Mercado de San Miguel","coordinates":[40.4154,-3.7091],"description":"Mercado de San Miguel earns its spot in the Sol & Centro food guide because it fills a clear meal role for this route. The polished market-hall choice near Plaza Mayor, best for groups and snack-led grazing rather than a quiet local meal. Use it when the group needs flexible grazing, uneven appetites, or a quick reset between sights.","price":"$","priceSource":"Time Out / Google Maps","hours":{"mon":"12:00 PM-12:00 AM","tue":"12:00 PM-12:00 AM","wed":"12:00 PM-12:00 AM","thu":"12:00 PM-12:00 AM","fri":"12:00 PM-1:00 AM","sat":"12:00 PM-1:00 AM","sun":"12:00 PM-12:00 AM"},"photo":"https://upload.wikimedia.org/wikipedia/commons/8/83/Mercado_de_San_Miguel_%28Madrid%29_01.jpg","poiId":"poi-spain-madrid-mercado-de-san-miguel"},{"id":"sol-food-san-gines","name":"Chocolatería San Ginés","coordinates":[40.4168,-3.7068],"description":"Chocolatería San Ginés earns its spot in the Sol & Centro food guide because it fills a clear meal role for this route. The central churros-and-chocolate classic, useful late, early, or as a sweet reset between Plaza Mayor and Sol. Use it when the route needs a focused sweet stop or casual reset rather than another full meal.","price":"$","priceSource":"Google Maps / Tripadvisor","hours":{"mon":"12:00 PM-12:00 AM","tue":"12:00 PM-12:00 AM","wed":"12:00 PM-12:00 AM","thu":"12:00 PM-12:00 AM","fri":"12:00 PM-1:00 AM","sat":"12:00 PM-1:00 AM","sun":"12:00 PM-12:00 AM"},"photo":"https://images.unsplash.com/photo-1613396874083-2d5fbe59ae79?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-madrid-chocolateria-san-gines"}],"sources":[{"name":"The Infatuation - Best Restaurants in Madrid","url":"https://www.theinfatuation.com/madrid/guides/best-madrid-restaurants"},{"name":"The Infatuation - Best Tapas Spots in Madrid","url":"https://www.theinfatuation.com/madrid/guides/best-tapas-spots-madrid"},{"name":"MICHELIN Guide - Madrid restaurants","url":"https://guide.michelin.com/us/en/comunidad-de-madrid/madrid/restaurants"},{"name":"Time Out Madrid - Restaurants","url":"https://www.timeout.es/madrid/es/restaurantes"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-madrid-sol-centro-popular-bars', 'madrid-sol-centro-popular-bars', 'Nightlife', 'Spain', 'Madrid', 'Sol & Centro', '{"id":"list-madrid-sol-centro-popular-bars","slug":"madrid-sol-centro-popular-bars","seoSlug":"best-bars","seoTitle":"Best Bars in Sol and Centro, Madrid","seoDescription":"Best bars in Sol and Centro, Madrid, covering historic taverns, central cocktail rooms, rooftop drinks, and late-night institutions.","title":"Central Drinks With a Reason","description":"Around Sol, the strongest nights are the ones with a specific room in mind: old taverns, rooftop views, piano-bar theater, and a few cocktail stops that justify staying central.","url":"https://www.google.com/maps/search/sol+centro+madrid+bars","category":"Nightlife","location":{"city":"Madrid","neighborhood":"Sol & Centro","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"sol-nightlife-casa-labra","name":"Casa Labra","coordinates":[40.4172,-3.7044],"description":"Casa Labra belongs in the Sol & Centro nightlife guide because it gives the night a defined role rather than another loose bar pin. A classic central beer-and-croquette counter that works as a first drink before the night gets more complicated. Use it when the group needs a clear mood, crowd, and second-stop direction before moving on.","hours":{"mon":"12:00 PM-11:00 PM","tue":"12:00 PM-11:00 PM","wed":"12:00 PM-11:00 PM","thu":"12:00 PM-11:30 PM","fri":"12:00 PM-12:00 AM","sat":"12:00 PM-12:00 AM","sun":"12:00 PM-10:30 PM"},"photo":"https://images.unsplash.com/photo-1515443961218-a51367888e4b?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-madrid-casa-labra"},{"id":"sol-nightlife-edition-roof","name":"The Madrid EDITION Roof","coordinates":[40.4171,-3.7062],"description":"The Madrid EDITION Roof belongs in the Sol & Centro nightlife guide because it gives the night a defined role rather than another loose bar pin. A polished rooftop above the central churn, useful when the plan needs skyline and hotel-bar control rather than tavern noise. Use it when the first drink should come with a view and an easy group meet-up point.","hours":{"mon":"6:00 PM-12:30 AM","tue":"6:00 PM-12:30 AM","wed":"6:00 PM-1:00 AM","thu":"6:00 PM-1:30 AM","fri":"6:00 PM-2:30 AM","sat":"6:00 PM-2:30 AM","sun":"6:00 PM-12:00 AM"},"photo":"https://images.unsplash.com/photo-1519671482749-fd09be7ccebf?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-madrid-the-madrid-edition-roof"},{"id":"sol-nightlife-toni2","name":"Toni 2 Piano Bar","coordinates":[40.421,-3.6976],"description":"Toni 2 Piano Bar belongs in the Sol & Centro nightlife guide because it gives the night a defined role rather than another loose bar pin. A late piano-bar institution near Gran Via where singing, crowd energy, and old Madrid showmanship are the point. Use it when the night is meant to continue past dinner into music, tickets, or a louder final room.","hours":{"mon":"10:00 PM-2:30 AM","tue":"10:00 PM-2:30 AM","wed":"10:00 PM-3:30 AM","thu":"10:00 PM-4:30 AM","fri":"10:00 PM-5:00 AM","sat":"10:00 PM-5:00 AM","sun":"10:00 PM-2:30 AM"},"photo":"https://images.unsplash.com/photo-1520523839897-bd0b52f945a0?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-madrid-toni-2-piano-bar"},{"id":"sol-nightlife-josealfredo","name":"Josealfredo","coordinates":[40.4214,-3.7028],"description":"Josealfredo belongs in the Sol & Centro nightlife guide because it gives the night a defined role rather than another loose bar pin. A central cocktail room that gives the Sol/Gran Via area a quieter, more deliberate drink before moving into Chueca or Malasana. Use it when one well-made drink is the event, not just a stop between bars.","hours":{"mon":"6:00 PM-12:30 AM","tue":"6:00 PM-12:30 AM","wed":"6:00 PM-1:00 AM","thu":"6:00 PM-1:30 AM","fri":"6:00 PM-2:30 AM","sat":"6:00 PM-2:30 AM","sun":"6:00 PM-12:00 AM"},"photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-madrid-josealfredo"}],"sources":[{"name":"Condé Nast Traveler - Best Bars in Madrid","url":"https://www.cntraveler.com/gallery/best-bars-in-madrid"},{"name":"World''s 50 Best Bars - Salmon Guru","url":"https://www.theworlds50best.com/bars/the-list/salmon-guru.html"},{"name":"World''s 50 Best Discovery - Angelita","url":"https://www.theworlds50best.com/discovery/Establishments/Spain/Madrid/Angelita.html"},{"name":"Time Out Madrid - Bars and pubs","url":"https://www.timeout.es/madrid/es/bares-y-pubs"},{"name":"Mondo Disko official","url":"https://www.mondodisko.es/en/mondo-disko/"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
