  ('list-madrid-sol-centro-culture', 'madrid-sol-centro-culture', 'Culture', 'Spain', 'Madrid', 'Sol & Centro', '{"id":"list-madrid-sol-centro-culture","slug":"madrid-sol-centro-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Sol and Centro, Madrid","seoDescription":"Best culture in Sol and Centro, Madrid, from Puerta del Sol and Plaza Mayor to the Royal Palace, Almudena, and old-city streets.","title":"Royal Madrid and Kilometer Zero","description":"Sol and Centro are the clearest introduction to Madrid''s civic and royal geography: kilometer zero, plaza life, palace rooms, cathedral scale, and old streets that still organize the center.","url":"https://www.google.com/maps/search/sol+centro+madrid+culture","category":"Culture","location":{"city":"Madrid","neighborhood":"Sol & Centro","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"sol-culture-puerta-del-sol","name":"Puerta del Sol","coordinates":[40.4169,-3.7036],"description":"Puerta del Sol earns the Sol & Centro culture slot because it turns the neighborhood route into more than scenery. Madrid''s kilometer-zero square and the easiest place to understand the city''s radial, crowded, ceremonial center. Use it to give the Sol & Centro route a concrete cultural anchor instead of only atmosphere.","hours":{"mon":"Open public space","tue":"Open public space","wed":"Open public space","thu":"Open public space","fri":"Open public space","sat":"Open public space","sun":"Open public space"},"photo":"https://upload.wikimedia.org/wikipedia/commons/f/f6/Puerta_del_Sol_%28Madrid%29_01.jpg","poiId":"poi-spain-madrid-puerta-del-sol"},{"id":"sol-culture-plaza-mayor","name":"Plaza Mayor","coordinates":[40.4155,-3.7074],"description":"Plaza Mayor earns the Sol & Centro culture slot because it turns the neighborhood route into more than scenery. The old central plaza for Habsburg Madrid, arcades, ceremonies, and the historic geometry around the market streets. Use it slowly, as a place to read the neighborhood rhythm rather than a quick photo pin.","hours":{"mon":"Open public space","tue":"Open public space","wed":"Open public space","thu":"Open public space","fri":"Open public space","sat":"Open public space","sun":"Open public space"},"photo":"https://upload.wikimedia.org/wikipedia/commons/4/44/Plaza_Mayor_de_Madrid_06.jpg","poiId":"poi-spain-madrid-plaza-mayor"},{"id":"sol-culture-royal-palace","name":"Royal Palace of Madrid","coordinates":[40.4179,-3.7143],"description":"Royal Palace of Madrid earns the Sol & Centro culture slot because it turns the neighborhood route into more than scenery. The royal-history anchor west of Sol, best paired with Plaza de Oriente, Almudena, and a La Latina evening. Use it slowly, as a place to read the neighborhood rhythm rather than a quick photo pin.","hours":{"mon":"9:00 AM-8:00 PM","tue":"9:00 AM-8:00 PM","wed":"9:00 AM-8:00 PM","thu":"9:00 AM-8:00 PM","fri":"9:00 AM-8:00 PM","sat":"9:00 AM-8:00 PM","sun":"9:00 AM-8:00 PM"},"photo":"https://upload.wikimedia.org/wikipedia/commons/5/5f/Palacio_Real_de_Madrid_2016_%282%29.jpg","poiId":"poi-spain-madrid-royal-palace-of-madrid"},{"id":"sol-culture-almudena","name":"Almudena Cathedral","coordinates":[40.4156,-3.7146],"description":"Almudena Cathedral earns the Sol & Centro culture slot because it turns the neighborhood route into more than scenery. The palace-side cathedral gives the Royal Madrid route a religious and architectural counterpoint. Pair it with nearby lanes and food stops so the history stays connected to the walk.","hours":{"mon":"9:00 AM-8:00 PM","tue":"9:00 AM-8:00 PM","wed":"9:00 AM-8:00 PM","thu":"9:00 AM-8:00 PM","fri":"9:00 AM-8:00 PM","sat":"9:00 AM-8:00 PM","sun":"9:00 AM-8:00 PM"},"photo":"https://upload.wikimedia.org/wikipedia/commons/0/0f/Catedral_de_la_Almudena_%28Madrid%29_01.jpg","poiId":"poi-spain-madrid-almudena-cathedral"}],"sources":[{"name":"Tourism Madrid","url":"https://www.esmadrid.com/en"},{"name":"Tourism Madrid - Prado Museum","url":"https://www.esmadrid.com/en/tourist-information/museo-del-prado"},{"name":"Tourism Madrid - Reina Sofia Museum","url":"https://www.esmadrid.com/en/tourist-information/reina-sofia-museum"},{"name":"Museo Nacional del Prado - Opening Times","url":"https://www.museodelprado.es/en/visit/opening-times-and-prices"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-madrid-letras-restaurants', 'madrid-barrio-de-las-letras-restaurants', 'Food', 'Spain', 'Madrid', 'Barrio de las Letras', '{"id":"list-madrid-letras-restaurants","slug":"madrid-barrio-de-las-letras-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Barrio de las Letras, Madrid","seoDescription":"Best restaurants in Barrio de las Letras, Madrid, for pre-theater dinners, tapas, taverns, modern Spanish rooms, and Art Walk meals.","title":"Pre-Theater Tables and Literary Taverns","description":"Las Letras works around museum days, theater starts, and late drinks. These picks keep meals close to Huertas, Cortes, and the Art Walk without falling into generic tapas traffic.","url":"https://www.google.com/maps/search/barrio+de+las+letras+madrid+restaurants","category":"Food","location":{"city":"Madrid","neighborhood":"Barrio de las Letras","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"letras-food-la-malontina","name":"La Malontina","coordinates":[40.4144,-3.6981],"description":"La Malontina earns its spot in the Barrio de las Letras food guide because it fills a clear meal role for this route. A compact Cortes dinner for modern Spanish plates, first dates, and pre-theater plans that need more care tha