  ('list-madrid-letras-culture', 'madrid-barrio-de-las-letras-culture', 'Culture', 'Spain', 'Madrid', 'Barrio de las Letras', '{"id":"list-madrid-letras-culture","slug":"madrid-barrio-de-las-letras-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Barrio de las Letras, Madrid","seoDescription":"Best culture in Barrio de las Letras, Madrid, from literary streets and Lope de Vega to Teatro Español, CaixaForum, and the Prado edge.","title":"Golden Age Streets and Art Walk Edges","description":"Las Letras is where Madrid culture becomes walkable: literary history, theater, narrow streets, museums at the edge, and plazas that still work after dark.","url":"https://www.google.com/maps/search/barrio+de+las+letras+madrid+culture","category":"Culture","location":{"city":"Madrid","neighborhood":"Barrio de las Letras","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"letras-culture-lope","name":"Casa Museo Lope de Vega","coordinates":[40.4142,-3.6978],"description":"Casa Museo Lope de Vega earns the Barrio de las Letras culture slot because it turns the neighborhood route into more than scenery. The most direct literary-house stop in the neighborhood, grounding the Golden Age story in a real domestic setting. Use it to gi