  ('list-madrid-retiro-popular-bars', 'madrid-retiro-bars', 'Nightlife', 'Spain', 'Madrid', 'Retiro', '{"id":"list-madrid-retiro-popular-bars","slug":"madrid-retiro-bars","seoSlug":"best-bars","seoTitle":"Best Bars in Retiro, Madrid","seoDescription":"Best bars in Retiro, Madrid, for park drinks, refined hotel bars, vermouth stops, and quieter nights around Ibiza and Jerónimos.","title":"Park Drinks and Quiet Finishes","description":"Retiro nightlife is not the loudest Madrid lane; it is best for polished drinks, vermouth, park terraces, and calmer second acts after museum-heavy days.","url":"https://www.google.com/maps/search/retiro+madrid+bars","category":"Nightlife","location":{"city":"Madrid","neighborhood":"Retiro","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"retiro-nightlife-florida","name":"Florida Retiro","coordinates":[40.4193,-3.6882],"description":"Florida Retiro belongs in the Retiro nightlife guide because it gives the night a defined role rather than another loose bar pin. The park''s most obvious dinner-to-drinks complex, useful when staying inside Retiro is the point. Use it when the group needs a clear mood, crowd, and second-stop direction before moving on.","hours":{"mon":"6:00 PM-12:30 AM","tue