  ('list-madrid-retiro-culture', 'madrid-retiro-culture', 'Culture', 'Spain', 'Madrid', 'Retiro', '{"id":"list-madrid-retiro-culture","slug":"madrid-retiro-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Retiro, Madrid","seoDescription":"Best culture in Retiro, Madrid, from El Retiro Park and Puerta de Alcalá to Prado-adjacent landmarks, museum edges, and garden walks.","title":"Park Culture and Prado Edges","description":"Retiro culture is part museum day, part green reset: monuments, gates, park routes, Prado edges, and the calm that keeps Madrid from becoming only plazas and late nights.","url":"https://www.google.com/maps/search/retiro+madrid+culture","category":"Culture","location":{"city":"Madrid","neighborhood":"Retiro","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"retiro-culture-park","name":"El Retiro Park","coordinates":[40.4153,-3.6844],"description":"El Retiro Park earns the Retiro culture slot because it turns the neighborhood route into more than scenery. Madrid''s central green reset, with lake walks, monuments, gardens, and enough scale to balance museum-heavy days. Use it as the route''s indoor anchor before letting Retiro open back into streets, meals, or evening stops.","hours":{"mon":"