  ('list-madrid-la-latina-culture', 'madrid-la-latina-culture', 'Culture', 'Spain', 'Madrid', 'La Latina', '{"id":"list-madrid-la-latina-culture","slug":"madrid-la-latina-culture","seoSlug":"best-culture","seoTitle":"Best Culture in La Latina, Madrid","seoDescription":"Best culture in La Latina, Madrid, from El Rastro and Plaza de la Paja to San Francisco el Grande, Cava Baja, and old Madrid streets.","title":"Markets, Plazas, and Old Madrid","description":"La Latina culture is less museum-based and more street-based: Sunday markets, layered plazas, old churches, tavern streets, and the feeling of Madrid before the avenues widen.","url":"https://www.google.com/maps/search/la+latina+madrid+culture","category":"Culture","location":{"city":"Madrid","neighborhood":"La Latina","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"latina-culture-rastro","name":"El Rastro","coordinates":[40.4086,-3.7071],"description":"El Rastro earns the La Latina culture slot because it turns the neighborhood route into more than scenery. Madrid''s famous Sunday flea market and the clearest cultural ritual around La Latina and Lavapies. Use it slowly, as a place to read the neighborhood rhythm rather than a quick photo pin.","hours":{"mon":"Closed"