  ('list-madrid-chueca-stays', 'madrid-chueca-hotels', 'Stay', 'Spain', 'Madrid', 'Chueca', '{"id":"list-madrid-chueca-stays","slug":"madrid-chueca-hotels","seoSlug":"best-places-to-stay","seoTitle":"Best Places to Stay in Chueca, Madrid","seoDescription":"Best places to stay in Chueca, Madrid, for LGBTQ+ nightlife, boutique hotels, Gran Via access, cocktail rooms, and stylish central sleep.","title":"Boutique Bases by the Nightlife","description":"Chueca is for travelers who want central Madrid with personality: design hotels, nightlife at the door, Gran Via close, and enough polish to make late nights easy.","url":"https://www.google.com/maps/search/chueca+madrid+hotels","category":"Stay","location":{"city":"Madrid","neighborhood":"Chueca","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"chueca-stay-only-you","name":"Only YOU Boutique Hotel Madrid","coordinates":[40.4235,-3.6964],"description":"Only YOU Boutique Hotel Madrid belongs in the Chueca stay guide because it solves a specific base tradeoff. A strong Chueca boutique stay with nightlife, shopping, and cocktail bars close without feeling like a hostel base. Choose it when budget, shared spaces, and meeting other travelers matter more than a quiet hotel reset.","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-madrid-only-you-boutique-hotel-madrid"},{"id":"chueca-stay-room-mate-oscar","name":"Room Mate Óscar","coordinates":[40.4206,-3.6981],"description":"Room Mate Óscar belongs in the Chueca stay guide because it solves a specific base tradeoff. A Plaza de Pedro Zerolo hotel for travelers who want Chueca energy and rooftop/social access right outside. Choose it when budget, shared spaces, and meeting other travelers matter more than a quiet hotel reset.","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-madrid-room-mate-oscar"},{"id":"chueca-stay-brach","name":"Brach Madrid","coordinates":[40.4198,-3.6995],"description":"Brach Madrid belongs in the Chueca stay guide because it solves a specific base tradeoff. A polished newer central hotel for travelers who want Gran Via and Chueca within a few blocks. Choose it when location, sleep quality, and budget need to be balanced honestly instead of picked by map distance alone.","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-madrid-brach-madrid"},{"id":"chueca-stay-urban","name":"Hotel Urban","coordinates":[40.4166,-3.699],"description":"Hotel Urban belongs in the Chueca stay guide because it solves a specific base tradeoff. A design-led luxury option between Chueca, Sol, and Las Letras for travelers who want central nightlife reach with a grown-up hotel feel. Choose it when service, quiet, and room quality should carry as much weight as location.","hours":{"mon":"24 hours","tue":"24 hours","wed":"24 hours","thu":"24 hours","fri":"24 hours","sat":"24 hours","sun":"24 hours"},"photo":"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-madrid-hotel-urban"}],"sources":[{"name":"Tourism Madrid - MICHELIN Key Hotels","url":"https://www.esmadrid.com/en/michelin-key-hotels"},{"name":"Condé Nast Traveler - Madrid hotels","url":"https://www.cntraveler.com/hotels/madrid"},{"name":"Hostelworld - Madrid Hostels","url":"https://www.hostelworld.com/hostels/europe/spain/madrid/"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-madrid-chueca-culture', 'madrid-chueca-culture', 'Culture', 'Spain', 'Madrid', 'Chueca', '{"id":"list-madrid-chueca-culture","slug":"madrid-chueca-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Chueca, Madrid","seoDescription":"Best culture in Chueca, Madrid, from Museo del Romanticismo and Plaza de Chueca to Gran Via architecture, galleries, and LGBTQ+ urban history.","title":"Romantic Rooms and Queer Madrid Streets","description":"Chueca culture is both formal and lived-in: museum interiors, Gran Via architecture, public plazas, LGBTQ+ nightlife history, and gallery streets toward Salesas.","url":"https://www.google.com/maps/search/chueca+madrid+culture","category":"Culture","location":{"city":"Madrid","neighborhood":"Chueca","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"chueca-culture-romanticismo","name":"Museo del Romanticismo","coordinates":[40.425,-3.6986],"description":"Museo del Romanticismo earns the Chueca culture slot because it turns the neighborhood route into more than scenery. A house-museum that gives Chueca/Salesas a quieter cultural stop away from the big Prado-triangle crowds. Use it as the route''s indoor anchor before letting Chueca open back into streets, meals, or evening stops.","hours":{"mon":"Closed","tue":"10:00 AM-7:00 PM","wed":"10:00 AM-7:00 PM","thu":"10:00 AM-7:00 PM","fri":"10:00 AM-7:00 PM","sat":"10:00 AM-7:00 PM","sun":"10:00 AM-7:00 PM"},"photo":"https://upload.wikimedia.org/wikipedia/commons/7/76/Museo_del_Romanticismo_%28Madrid%29_01.jpg","poiId":"poi-spain-madrid-museo-del-romanticismo"},{"id":"chueca-culture-plaza","name":"Plaza de Chueca","coordinates":[40.4227,-3.6976],"description":"Plaza de Chueca earns the Chueca culture slot because it turns the neighborhood route into more than scenery. The neighborhood''s social center and a compact way to understand Chueca''s identity as a public, queer, central Madrid space. Use it slowly, as a place to read the neighborhood rhythm rather than a quick photo pin.","hours":{"mon":"Open public space","tue":"Open public space","wed":"Open public space","thu":"Open public space","fri":"Open public space","sat":"Open public space","sun":"Open public space"},"photo":"https://images.unsplash.com/photo-1539037116277-4db20889f2d4?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-madrid-plaza-de-chueca"},{"id":"chueca-culture-gran-via","name":"Gran Vía","coordinates":[40.42,-3.7016],"description":"Gran Vía earns the Chueca culture slot because it turns the neighborhood route into more than scenery. The architectural and theatrical boulevard that frames Chueca''s southern edge and links the neighborhood to central Madrid spectacle. Use it to give the Chueca route a concrete cultural anchor instead of only atmosphere.","hours":{"mon":"Open public space","tue":"Open public space","wed":"Open public space","thu":"Open public space","fri":"Open public space","sat":"Open public space","sun":"Open public space"},"photo":"https://upload.wikimedia.org/wikipedia/commons/5/5b/Gran_V%C3%ADa_%28Madrid%29_1.jpg","poiId":"poi-spain-madrid-gran-via"},{"id":"chueca-culture-longoria","name":"Palacio de Longoria","coordinates":[40.4247,-3.6968],"description":"Palacio de Longoria earns the Chueca culture slot because it turns the neighborhood route into more than scenery. A modernista landmark on the Salesas edge, useful for reading the neighborhood''s architecture beyond bars and shops. Use it to give the Chueca route a concrete cultural anchor instead of only atmosphere.","hours":{"mon":"Open public space","tue":"Open public space","wed":"Open public space","thu":"Open public space","fri":"Open public space","sat":"Open public space","sun":"Open public space"},"photo":"https://upload.wikimedia.org/wikipedia/commons/0/07/Palacio_de_Longoria_%28Madrid%29_01.jpg","poiId":"poi-spain-madrid-palacio-de-longoria"}],"sources":[{"name":"Tourism Madrid","url":"https://www.esmadrid.com/en"},{"name":"Tourism Madrid - Prado Museum","url":"https://www.esmadrid.com/en/tourist-information/museo-del-prado"},{"name":"Tourism Madrid - Reina Sofia Museum","url":"https://www.esmadrid.com/en/tourist-information/reina-sofia-museum"},{"name":"Museo Nacional del Prado - Opening Times","url":"https://www.museodelprado.es/en/visit/opening-times-and-prices"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-r-history-magellan-elcano-circumnavigation', 'magellan-elcano-first-voyage-around-the-world', 'Culture', 'World', null, null, '{"id":"list-r-history-magellan-elcano-circumnavigation","slug":"magellan-elcano-first-voyage-around-the-world","seoSlug":"magellan-elcano-circumnavigation-route","seoTitle":"Magellan-Elcano First Voyage Around the World Route","seoDescription":"A mapped historical journey following the 1519-1522 Magellan-Elcano circumnavigation from Spain across the Atlantic, Pacific, Indian Ocean, and back.","title":"Magellan-Elcano: First Voyage Around the World","description":"Trace the 1519-1522 expedition from Seville and Sanlucar through South America, the Pacific, the Philippines, the Spice Islands, the Indian Ocean, and the return to Spain. Magellan led the voyage, but Juan Sebastian Elcano and the Victoria completed the circumnavigation.","photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Magellan_Elcano_Circumnavigation-en.svg","url":"https://www.google.com/maps/search/Magellan-Elcano+circumnavigation+route","category":"Culture","location":{"country":"World","continent":"Global","scope":"continent"},"creator":{"id":"user-rguide-history","name":"R History","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-04T00:00:00.000Z","stops":[{"id":"magellan-sanlucar-departure","name":"Sanlucar de Barrameda","coordinates":[36.7787,-6.3515],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Sanlucar_barrameda_ocaso_desde_bajo_guia.jpg","hours":"September 20, 1519","description":"The fleet left Sanlucar at the mouth of the Guadalquivir, turning a royal contract signed inland at Seville into an ocean voyage. This is the threshold between preparation and risk: five ships, a multinational crew, and a westward plan to reach the Spice Islands without crossing Portuguese-controlled waters.","poiId":"poi-world-sanlucar-de-barrameda"},{"id":"magellan-canary-islands","name":"Canary Islands","coordinates":[28.2916,-16.6291],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Teide_from_north_2006.jpg","hours":"September 26, 1519","description":"The Canaries were the fleet''s last familiar Atlantic provisioning stop before committing to the long southwest crossing. From here the expedition moved out of routine Iberian sailing lanes and into the practical problem that defined the voyage: finding a passage through an unknown American coastline.","poiId":"poi-world-canary-islands"},{"id":"magellan-santa-lucia-bay","name":"Santa Lucia Bay / Rio de Janeiro Bay","coordinates":[-22.9068,-43.1729],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Ba%C3%ADa_de_Guanabara_vista_do_P%C3%A3o_de_A%C3%A7%C3%BAcar_2020.jpg","hours":"December 13, 1519","description":"After crossing the Atlantic, the ships reached Santa Lucia Bay, now Rio de Janeiro Bay. This Brazil stop gave the crew water, food, repairs, and a first sustained encounter with the South American coast before the voyage shifted from crossing ocean to probing shoreline for a hidden route west.","poiId":"poi-world-santa-lucia-bay-rio-de-janeiro-bay"},{"id":"magellan-rio-de-solis","name":"Rio de Solis / Rio de la Plata","coordinates":[-34.9011,-56.1645],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Rio_de_la_Plata_BA_2.JPG","hours":"January 12, 1520","description":"At Rio de Solis, now the Rio de la Plata, the fleet investigated a vast estuary that looked like it might be the long-sought passage. It was not, but the stop captures the uncertainty of the search: every inlet along the coast had to be tested before Magellan could rule it out.","poiId":"poi-world-rio-de-solis-rio-de-la-plata"},{"id":"magellan-puerto-san-julian","name":"Puerto San Julian","coordinates":[-49.3069,-67.7298],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Puerto_San_julian_santa_cruz_argentina.jpg","hours":"March 31, 1520","description":"Puerto San Julian became the expedition''s winter anchorage and its political breaking point. Cold, hunger, and doubt fed a mutiny among Spanish captains, and Magellan''s harsh suppression of it kept the voyage alive while also revealing how fragile command had become so far from Spain.","poiId":"poi-world-puerto-san-julian"},{"id":"magellan-cabo-virgenes","name":"Cabo Virgenes / Cape Virgenes","coordinates":[-52.3333,-68.35],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Faro_en_Cabo_V%C3%ADrgenes_2719.jpg","hours":"October 21, 1520","description":"Cabo Virgenes marked the eastern mouth of the passage Magellan had been seeking for more than a year. The fleet entered cautiously, because this could still have been another dead-end bay, but the geography finally began to open into a navigable route through the southern continent.","poiId":"poi-world-cabo-virgenes-cape-virgenes"},{"id":"magellan-strait","name":"All Saints Strait / Strait of Magellan","coordinates":[-53.1638,-70.9171],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/StraitOfMagellan.jpg","hours":"November 28, 1520","description":"The route through All Saints Strait, later named the Strait of Magellan, solved the voyage''s central navigational problem. One ship deserted during the passage, but the remaining vessels emerged into the ocean Magellan named the Pacific, changing the scale of the expedition overnight.","poiId":"poi-world-all-saints-strait-strait-of-magellan"},{"id":"magellan-cabo-deseado","name":"Cabo Deseado","coordinates":[-53,-74.35],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Map_of_the_Strait_of_Magellan_Developed_by_the_Schouten_and_Le_Maire_Expedition%2C_1616_WDL3971.png","hours":"November 28, 1520","description":"Cabo Deseado marks the western exit from the strait on the route map. It is less a settlement stop than a passage marker: the moment the expedition left the maze of Patagonian channels and committed to an ocean crossing far larger than anyone aboard expected.","poiId":"poi-world-cabo-deseado"},{"id":"magellan-sharks-islands","name":"Sharks'' Islands / Puka-Puka","coordinates":[-14.8208,-138.8128],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Pukapuka_Aerial_efs_1280.jpg","hours":"January 21, 1521","description":"The Sharks'' Islands, often identified with Puka-Puka, appear on the route as a pass-by rather than a true relief stop. Their importance is scale: after weeks of hunger and illness, even a remote atoll became a navigational clue in an ocean the expedition badly underestimated.","poiId":"poi-world-sharks-islands-puka-puka"},{"id":"magellan-san-pablo-island","name":"San Pablo Island / Vostok Island or Flint Island","coordinates":[-10.1,-152.3],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Vostok_Island_AKK.jpg","hours":"February 4, 1521","description":"San Pablo Island, commonly associated with Vostok Island or Flint Island, was another lonely Pacific pass-by. It shows the brutal sparseness of this leg: the fleet could sight land and still fail to find the water, food, or anchorage needed to recover.","poiId":"poi-world-san-pablo-island-vostok-island-or-flint-island"},{"id":"magellan-ladrones-islands","name":"Ladrones Islands / Mariana Islands","coordinates":[13.4443,144.7937],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Umatac_Bay%2C_Guam_-_DSC00951.JPG","hours":"March 6, 1521","description":"The fleet reached the Ladrones Islands, now the Marianas, after the punishing Pacific crossing. Guam brought contact, conflict, and desperately needed supplies; it also confirmed that the expedition had crossed a true ocean, not the narrower sea imagined before departure.","poiId":"poi-world-ladrones-islands-mariana-islands"},{"id":"magellan-samar","name":"Samar","coordinates":[11.6,125],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Islands_of_Samar_and_Leyte_from_space.jpg","hours":"March 16, 1521","description":"Samar is the first Philippine landfall marked on the route. For the exhausted crews, it signaled entry into a new island world of pilots, trade networks, languages, and alliances that would shape the next phase more than open-ocean navigation did.","poiId":"poi-world-samar"},{"id":"magellan-homonhon","name":"Homonhon","coordinates":[10.75,125.72],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Homonhon_Island%2C_Guiuan%2C_Eastern_Samar_at_sunset.jpg","hours":"March 17, 1521","description":"Homonhon was the first Philippine stopover after landfall. The anchorage gave the crew a chance to recover from the Pacific crossing and began the sequence of local encounters that pulled Magellan from exploration into diplomacy and power politics.","poiId":"poi-world-homonhon"},{"id":"magellan-limasawa","name":"Limasawa","coordinates":[9.938,125.074],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/First_Mass_in_the_Philippines.jpg","hours":"March 28, 1521","description":"Limasawa sits between Homonhon and Cebu in the Philippine stage of the voyage. It matters because the expedition was no longer simply surviving; it was being guided through regional waters by local knowledge and entering a dense political landscape.","poiId":"poi-world-limasawa"},{"id":"magellan-cebu","name":"Cebu","coordinates":[10.3157,123.8854],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Magellan%27s_Cross%2C_Cebu_City%2C_Jan_2024.jpg","hours":"April 7, 1521","description":"Cebu became the expedition''s central Philippine alliance stop. Magellan negotiated with Rajah Humabon, staged conversions, and tried to bind navigation, trade, and Christian empire into one project, a choice that soon pulled him into conflicts the fleet did not understand.","poiId":"poi-world-cebu"},{"id":"magellan-mactan","name":"Mactan","coordinates":[10.3103,123.9494],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/MactanShrine.jpg","hours":"April 27, 1521","description":"Mactan is the rupture point of the journey. Magellan was killed in battle against forces led by Lapulapu, so the voyage remembered under his name was completed without him by survivors who now had to escape the political consequences of his final gamble.","poiId":"poi-world-mactan"},{"id":"magellan-palawan","name":"Palawan","coordinates":[9.8349,118.7384],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/El_Nido_Palawan.jpg","hours":"June 21, 1521","description":"Palawan appears after the crisis at Cebu and Mactan as the remaining expedition searched for pilots, food, and a route onward. The voyage was now smaller, weaker, and more dependent on local maritime expertise to reach the Spice Islands.","poiId":"poi-world-palawan"},{"id":"magellan-brunei","name":"Brunei","coordinates":[4.9031,114.9398],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Omar_Ali_Saifuddien_Mosque%2C_Bandar_Seri_Begawan.jpg","hours":"August 17-September 21, 1521","description":"Brunei was a major stop in a wealthy trading world already connected across Southeast Asia. For the surviving crew, it showed that the expedition had reached the commercial networks it sought, but still had to navigate politics, suspicion, and scarcity before reaching the Moluccas.","poiId":"poi-world-brunei"},{"id":"magellan-tidore","name":"Tidore","coordinates":[0.6966,127.4361],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Tidore_Island_Indonesia_Daytime.jpg","hours":"November 8, 1521","description":"Tidore was the commercial destination: the Spice Islands that made the whole risky westward route worth attempting. Here the surviving ships loaded cloves, proving the route could reach Asia from the west even though the cost in ships and lives had been staggering.","poiId":"poi-world-tidore"},{"id":"magellan-ambon","name":"Ambon Island","coordinates":[-3.6554,128.1908],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Ambon%2C_Maluku%2C_Indonesia.jpg","hours":"December 29, 1521","description":"Ambon belongs to the homeward leg under Elcano, after the expedition had split around the damaged Trinidad and the Victoria''s desperate westward return. It marks the shift from reaching the Spice Islands to surviving the escape from them.","poiId":"poi-world-ambon-island"},{"id":"magellan-timor","name":"Timor","coordinates":[-9.175,124.65],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Landscape_in_East_Timor.jpg","hours":"January 25, 1522","description":"Timor was the last major Southeast Asian point before the Victoria crossed the Indian Ocean. From here Elcano avoided Portuguese ports where possible, choosing a dangerous open-ocean return over capture on the established eastern route.","poiId":"poi-world-timor"},{"id":"magellan-cape-good-hope","name":"Cape of Good Hope","coordinates":[-34.3568,18.474],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Cape_Point_at_Cape_of_Good_hope_Aerial_View_-_panoramio.jpg","hours":"May 19, 1522","description":"Passing the Cape of Good Hope put the Victoria back into the Atlantic world, but not into safety. Elcano''s crew was starving, the ship was worn down, and the Portuguese-controlled route around Africa forced them to keep moving with little margin for repair or rest.","poiId":"poi-world-cape-of-good-hope"},{"id":"magellan-cape-verde","name":"Cape Verde Islands","coordinates":[16.886,-24.988],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Coastline_Santo_Antao.JPG","hours":"July 9, 1522","description":"Cape Verde was the final danger point before Spain. The crew tried to obtain supplies while hiding the fact that they had come from the Spice Islands by sailing westward; Portuguese authorities detained some men, and the Victoria escaped with only a remnant aboard.","poiId":"poi-world-cape-verde-islands"},{"id":"magellan-sanlucar-return","name":"Sanlucar de Barrameda Return","coordinates":[36.7787,-6.3515],"photo":"https://commons.wikimedia.org/wiki/Special:FilePath/Magellan_Nao_Victoria_return_memorial%2C_1522_AD_-_Cathedral_of_Seville_-_Sevilla%2C_Spain_-_DSC07584.JPG","hours":"September 6, 1522","description":"The Victoria returned to Sanlucar with eighteen surviving Europeans aboard, closing the first recorded circumnavigation. The route ended where it began, but the meaning had changed: the world was now proven navigable as a connected ocean system, at enormous human cost.","poiId":"poi-world-sanlucar-de-barrameda-return"}],"sources":[{"name":"Encyclopaedia Britannica - Ferdinand Magellan, Circumnavigation of the globe","url":"https://www.britannica.com/biography/Ferdinand-Magellan/Circumnavigation-of-the-globe"},{"name":"HISTORY - Magellan''s expedition circumnavigates globe","url":"https://www.history.com/this-day-in-history/magellans-expedition-circumnavigates-globe"},{"name":"JSTOR - Antonio Pigafetta, First Voyage Around the World","url":"https://www.jstor.org/stable/10.3138/9781442684928"},{"name":"Origins - Magellan''s Circumnavigation of the Earth","url":"https://origins.osu.edu/milestones/magellan-circumnavigation-earth"},{"name":"Wikimedia Commons - Magellan Elcano Circumnavigation route map","url":"https://commons.wikimedia.org/wiki/File:Magellan_Elcano_Circumnavigation-en.svg"}]}'::jsonb),
  ('list-barcelona-top-parks', 'barcelona-top-parks-in-the-city', 'Nature', 'Spain', 'Barcelona', null, '{"id":"list-barcelona-top-parks","slug":"barcelona-top-parks-in-the-city","seoSlug":"best-parks","seoTitle":"Best Parks in Barcelona","seoDescription":"Best parks in Barcelona for Gaudi architecture, hilltop views, historic gardens, Ciutadella lawns, Montjuic walks, and green spaces worth saving.","title":"Green Escapes and Hilltop Views","description":"Use this when the day needs air between dense neighborhoods: Gaudi mosaics, Ciutadella lawns, Montjuic paths, rose beds, and hilltop viewpoints that turn a walk into a real route without leaving the city behind.","url":"https://www.google.com/maps/search/top+parks+in+barcelona","category":"Nature","location":{"city":"Barcelona","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-04-17T00:00:00.000Z","stops":[{"id":"park-guell","name":"Parc Guell","coordinates":[41.4145,2.1527],"description":"Parc Guell is the nature guide''s architecture-meets-viewpoint anchor, combining Gaudi''s sculptural landscape, mosaic terraces, and hillside city views. Book the monumental zone when needed and treat the visit as a planned half-day stop rather than a casual park detour.","hours":{"default":"Daily ~9:30 AM-7:30 PM."},"photo":"https://estatics-nasia.dtibcn.cat/nasia-pro/media/2016%2C06%2CAZ8Q8387-C%25C3%25B2pia-760x428.jpg","poiId":"poi-spain-barcelona-parc-guell"},{"id":"parc-de-la-ciutadella","name":"Parc de la Ciutadella","coordinates":[41.3888,2.186],"description":"Parc de la Ciutadella gives the list its central, easy-access green space, with 19th-century exhibition history, the Cascada Monumental, lake boating, and broad lawns. Use it as the reset between El Born, the zoo edge, and the waterfront when the route needs open air without leaving the center.","hours":{"default":"Daily ~10:00 AM-10:30 PM."},"photo":"https://estatics-nasia.dtibcn.cat/nasia-pro/media/2015%2C12%2CAZ8Q2726-760x428.jpg","poiId":"poi-spain-barcelona-parc-de-la-ciutadella"},{"id":"montjuic-park","name":"Montjuic Park","coordinates":[41.363,2.1679],"description":"Montjuic Park is the big hill-day pick, linking gardens, lookouts, museums, castle approaches, Olympic-era venues, and botanical spaces. It is best for travelers who want nature, culture, and views in one slower route rather than a single quick photo stop.","hours":{"default":"Park 24h; gardens/sites ~10:00 AM-sunset."},"photo":"https://www.barcelona.cat/sites/default/files/styles/facebook/public/montjuic_d_600x315_2.jpg?itok=eZrB9ZmW","poiId":"poi-spain-barcelona-montjuic-park"},{"id":"parc-del-laberint-dhorta","name":"Parc del Laberint d''Horta","coordinates":[41.4397,2.1477],"description":"Parc del Laberint d''Horta brings a quieter garden experience to the guide, with an 18th-century cypress maze, neoclassical design, and romantic landscaping near Collserola. Use it when the city center feels too dense and the plan can support a more intentional trip north.","hours":{"winter":"10:00 AM-6:00 PM","spring":"10:00 AM-7:00 PM","summer":"10:00 AM-8:00 PM","fall":"10:00 AM-7:00 PM"},"photo":"https://estatics-nasia.dtibcn.cat/nasia-pro/media/2016%2C01%2CAZ8Q6392-760x428.jpg","poiId":"poi-spain-barcelona-parc-del-laberint-d-horta"},{"id":"parc-de-cervantes","name":"Parc de Cervantes","coordinates":[41.3871,2.1123],"description":"Parc de Cervantes earns its place through the rose collection, with thousands of bushes and peak blooms from late spring into summer. It is a seasonal, calmer Pedralbes stop that works best when the route is already leaning west or needs a quieter garden break.","hours":{"default":"Daily 8:00 AM-sunset."},"photo":"https://estatics-nasia.dtibcn.cat/nasia-pro/media/2016%2C01%2CAZ8Q3185-760x428.jpg","poiId":"poi-spain-barcelona-parc-de-cervantes"},{"id":"parc-del-guinardo-bunkers-del-carmel","name":"Parc del Guinardo / Bunkers del Carmel","coordinates":[41.4183,2.1527],"description":"Parc del Guinardo and the Bunkers del Carmel give the guide its strongest panoramic payoff, with Turo de la Rovira''s former anti-aircraft battery remains and wide skyline views. Go for sunset or clear-weather views, but plan the climb and crowds instead of treating it like a simple neighborhood park.","hours":{"default":"Park 24h; Bunkers ~8:30 AM-7:30 PM (night-restricted)."},"photo":"https://thirdeyetraveller.com/wp-content/uploads/Carmel-del-Bunkers-Barcelona-6.jpg","poiId":"poi-spain-barcelona-parc-del-guinardo-bunkers-del-carmel"}],"sources":[{"name":"Turisme de Barcelona - Parks & Gardens","url":"https://www.barcelonaturisme.com/wv3/en/page/32/parks-and-gardens.html"},{"name":"Ajuntament de Barcelona - Parks directory","url":"https://ajuntament.barcelona.cat/ecologiaurbana/en/services/the-city-works/parks-and-gardens"},{"name":"Lonely Planet - Best parks in Barcelona","url":"https://www.lonelyplanet.com/articles/best-parks-barcelona"},{"name":"Time Out - Best parks and gardens in Barcelona","url":"https://www.timeout.com/barcelona/things-to-do/best-parks-in-barcelona"},{"name":"Conde Nast Traveler - Barcelona destination","url":"https://www.cntraveler.com/destinations/barcelona"},{"name":"Park Guell official","url":"https://parkguell.barcelona/en"},{"name":"UNESCO - Works of Antoni Gaudi","url":"https://whc.unesco.org/en/list/320"},{"name":"Parc de la Ciutadella page","url":"https://www.barcelonaturisme.com/wv3/en/page/117/parc-de-la-ciutadella.html"},{"name":"Montjuic page","url":"https://www.barcelonaturisme.com/wv3/en/page/120/montjuic.html"},{"name":"Parc del Laberint d''Horta page","url":"https://www.barcelonaturisme.com/wv3/en/page/118/parc-del-laberint-dhorta.html"},{"name":"Parc de Cervantes page","url":"https://www.barcelonaturisme.com/wv3/en/page/119/parc-de-cervantes.html"},{"name":"Turo de la Rovira / Bunkers del Carmel page","url":"https://www.barcelonaturisme.com/wv3/en/page/124/turo-de-la-rovira.html"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Tripadvisor - Barcelona parks attractions","url":"https://www.tripadvisor.com/Attractions-g187497-Activities-c57-Barcelona_Catalonia.html"}]}'::jsonb),
  ('list-barcelona-gothic-quarter-restaurants', 'barcelona-gothic-quarter-restaurants', 'Food', 'Spain', 'Barcelona', 'Gothic Quarter', '{"id":"list-barcelona-gothic-quarter-restaurants","slug":"barcelona-gothic-quarter-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in the Gothic Quarter, Barcelona","seoDescription":"Best restaurants in the Gothic Quarter, Barcelona, from historic Catalan dining rooms to modern tasting menus and old-town spots that avoid the tourist-trap pattern.","title":"Old-City Tables That Hold Up","description":"The Gothic Quarter can punish lazy restaurant searches, so this guide favors rooms with a reason to book: Catalan taverns, compact bistros, robata counters, and small tasting menus that hold their own inside the tourist-heavy lanes.","url":"https://www.google.com/maps/search/gothic+quarter+restaurants+barcelona","category":"Food","location":{"city":"Barcelona","neighborhood":"Gothic Quarter","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-04-29T00:00:00.000Z","stops":[{"id":"gothic-la-sosenga","name":"La Sosenga","coordinates":[41.3826,2.1749],"description":"Source cross-checks point to La Sosenga as one of the stronger food-first choices inside the Gothic Quarter: a small Catalan room that updates older recipes through seasonal, tasting-menu-style cooking rather than leaning on old-city atmosphere alone. Time Out and map-review signals support it as a better reservation for diners who want regional cooking, careful plating, and a quieter meal than the tourist-heavy lanes usually provide.","price":"$$","priceSource":"Time Out","hours":{"mon":"Closed","tue":"1:00 PM-4:00 PM","wed":"1:00 PM-4:00 PM","thu":"1:00 PM-4:00 PM","fri":"1:00 PM-4:00 PM, 8:00 PM-11:00 PM","sat":"1:00 PM-4:00 PM, 8:00 PM-11:00 PM","sun":"Closed"},"photo":"https://images.gestionaweb.cat/7664/img-2560-1440/captura-de-pantalla-2025-09-24-a-les-9-24-50.png","poiId":"poi-spain-barcelona-la-sosenga"},{"id":"gothic-bistrot-levante","name":"Bistrot Levante","coordinates":[41.3833,2.1769],"description":"Eater''s Old City coverage and Google Maps signals make Bistrot Levante useful as a modern counterpoint to the Gothic Quarter''s traditional taverns. The draw is not landmark history; it is a compact bistro on Placeta de Manuel Ribé with Eastern Mediterranean flavors, good vegetable-forward plates, and a calmer room that works for lunch or dinner when nearby streets are packed.","price":"$$","priceSource":"Eater / Google Maps","hours":{"mon":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","tue":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","wed":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","thu":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","fri":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sat":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sun":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM"},"photo":"https://images.unsplash.com/photo-1552566626-52f8b828add9?auto=format&fit=crop&w=900&q=80","poiId":"poi-spain-barcelona-bistrot-levante"},{"id":"gothic-kak-koy","name":"Kak Koy","coordinates":[41.385,2.1755],"description":"Kak Koy is included as the high-end, source-backed alternative in the Gothic core: Eater highlights its robata approach, and map/booking signals show it functions more like a focused Japanese grill counter than a broad tapas stop. It is best for diners who want Barcelona seafood and market produce filtered through precise charcoal cooking, bar seating, and a reservation-led dinner rhythm.","price":"$$$","priceSource":"Eater / Google Maps","hours":{"mon":"Closed","tue":"7:00 PM-10:30 PM","wed":"7:00 PM-10:30 PM","thu":"7:00 PM-10:30 PM","fri":"7:00 PM-10:30 PM","sat":"7:00 PM-10:30 PM","sun":"Closed"},"photo":"https://www.kakure.es/wp-content/uploads/young-asian-woman-eating-sashimi-set-in-japanese-r-2023-11-27-04-59-45-utc.jpg","poiId":"poi-spain-barcelona-kak-koy"},{"id":"gothic-la-plata-restaurant","name":"Bar La Plata","coordinates":[41.3818,2.1799],"description":"Bar La Plata earns its spot through longevity, traveler-review consistency, and a menu that has stayed intentionally short since 1945. The value is the whole old-tavern package: fried fish, tomato salad, butifarra, house wine, fast counter service, and a room that still feels local despite being deep in the Gothic Quarter.","price":"$","priceSource":"Tripadvisor / Google Maps","hours":{"mon":"Closed","tue":"12:00 PM-3:30 PM, 7:00 PM-11:00 PM","wed":"12:00 PM-3:30 PM, 7:00 PM-11:00 PM","thu":"12:00 PM-3:30 PM, 7:00 PM-11:00 PM","fri":"12:00 PM-3:30 PM, 7:00 PM-11:00 PM","sat":"12:00 PM-3:30 PM, 7:00 PM-11:00 PM","sun":"Closed"},"photo":"https://barlaplata.com/wp-content/uploads/2024/04/img_7003-1.jpg","poiId":"poi-spain-barcelona-bar-la-plata"},{"id":"gothic-capet","name":"Capet","coordinates":[41.3816,2.1764],"description":"Capet is the polished small-restaurant pick in this set, supported by MICHELIN and reservation-platform signals rather than social hype. It works for a serious dinner in the Gothic lanes: contemporary Catalan cooking, a controlled chef-led menu, and enough intimacy to feel special without the scale or price jump of Barcelona''s major destination tasting rooms.","price":"$$$","priceSource":"MICHELIN Guide / Resy","hours":{"mon":"Closed","tue":"7:00 PM-10:30 PM","wed":"7:00 PM-10:30 PM","thu":"7:00 PM-10:30 PM","fri":"7:00 PM-10:30 PM","sat":"7:00 PM-10:30 PM","sun":"Closed"},"photo":"https://static.wixstatic.com/media/fdc945_2b2a24bff92540c8b37ff6bd1c06be5a~mv2.jpg/v1/fill/w_1024,h_683,al_c/fdc945_2b2a24bff92540c8b37ff6bd1c06be5a~mv2.jpg","poiId":"poi-spain-barcelona-capet"},{"id":"gothic-sensi-bistro","name":"Sensi Bistro","coordinates":[41.3803,2.1771],"description":"Sensi Bistro stays on the list because Tripadvisor and Google Maps show sustained demand from visitors looking for creative tapas that are more composed than the surrounding old-city churn. It is group-friendly, shareable, and practical near Plaça Reial, with the caveat that it is more polished international bistro-tapas than a hidden local institution.","price":"$$","priceSource":"Tripadvisor / Google Maps","hours":{"mon":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","tue":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","wed":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","thu":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","fri":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sat":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sun":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM"},"photo":"https://www.barcelona-life.com/wp-content/uploads/2022/02/le-bistro-sensi-barcelona.jpg","poiId":"poi-spain-barcelona-sensi-bistro"}],"sources":[{"name":"Time Out - Best restaurants in Barcelona","url":"https://www.timeout.com/barcelona/restaurants/best-restaurants-in-barcelona"},{"name":"The Infatuation - Best Restaurants in Barcelona","url":"https://www.theinfatuation.com/barcelona/guides/best-restaurants-hotels-barcelona"},{"name":"Eater - Old City restaurants","url":"https://www.eater.com/maps/barcelona-old-city-gothic-quarter-best-restaurants"},{"name":"MICHELIN Guide - Capet","url":"https://guide.michelin.com/us/en/catalunya/barcelona/restaurant/capet"},{"name":"Restaurants for Kings - Gothic Quarter restaurants","url":"https://restaurantsforkings.com/blog/gothic-quarter-barcelona-restaurants-guide-2026.html"},{"name":"Tripadvisor - Gothic Quarter restaurants","url":"https://www.tripadvisor.com/Restaurants-g187497-zfn7237169-Barcelona_Catalonia.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-barcelona-el-born-restaurants', 'barcelona-el-born-restaurants', 'Food', 'Spain', 'Barcelona', 'El Born', '{"id":"list-barcelona-el-born-restaurants","slug":"barcelona-el-born-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in El Born, Barcelona","seoDescription":"Best restaurants in El Born, Barcelona, including seafood counters, natural-wine rooms, tapas classics, market-adjacent kitchens, and booking-worthy local favorites.","title":"Cava, Counters, and Cool Rooms","description":"El Born works best when dinner stays close to the neighborhood''s museum streets and late-night pulse. This guide mixes seafood counters, cava rooms, natural-wine dinners, market-adjacent kitchens, and a few places that justify the crowd.","url":"https://www.google.com/maps/search/el+born+restaurants+barcelona","category":"Food","location":{"city":"Barcelona","neighborhood":"El Born","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-04-29T00:00:00.000Z","stops":[{"id":"born-cal-pep-restaurant","name":"Cal Pep","coordinates":[41.3835,2.1839],"description":"Cal Pep is a Born classic repeatedly validated by editorial guides and traveler demand: the experience centers on the counter, rapid-fire seafood tapas, and letting the kitchen steer you through clams, squid, fried fish, and seasonal specials. It is expensive for the format, but the draw is the performance of the room as much as the food.","price":"$$$","priceSource":"The Infatuation / Google Maps","hours":{"mon":"Closed","tue":"1:00 PM-3:30 PM, 8:00 PM-11:00 PM","wed":"1:00 PM-3:30 PM, 8:00 PM-11:00 PM","thu":"1:00 PM-3:30 PM, 8:00 PM-11:00 PM","fri":"1:00 PM-3:30 PM, 8:00 PM-11:30 PM","sat":"1:00 PM-3:30 PM, 8:00 PM-11:30 PM","sun":"Closed"},"photo":"https://static.wixstatic.com/media/57144e_89f865012fdb4db8bc8bec1b2fdeede3~mv2.jpg","poiId":"poi-spain-barcelona-cal-pep"},{"id":"born-bar-del-pla-restaurant","name":"Bar del Pla","coordinates":[41.3857,2.1817],"description":"Bar del Pla is supported by The Infatuation, Google Maps, and natural-wine chatter as one of El Born''s more reliable modern tapas rooms. It balances Catalan comfort, creative small plates, and a bistro-like wine program, making it a strong booking when you want the neighborhood''s energy without defaulting to a tourist-facing tapas counter.","price":"$$","priceSource":"The Infatuation / Google Maps","hours":{"mon":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","tue":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","wed":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","thu":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","fri":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sat":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sun":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM"},"photo":"https://barcelonanavigator.com/wp-content/uploads/2016/05/Jordi.jpg","poiId":"poi-spain-barcelona-bar-del-pla"},{"id":"born-fismuler","name":"Fismuler","coordinates":[41.3867,2.1846],"description":"Fismuler is a higher-price Born pick because sources consistently frame it as a destination meal, not just a neighborhood stop. The appeal is raw seafood, seasonal Mediterranean plates, a stylish Rec Comtal dining room, and the now-famous cheesecake; it suits a longer dinner where design, wine, and pacing matter.","price":"$$$","priceSource":"The Infatuation / Google Maps","hours":{"mon":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","tue":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","wed":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","thu":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","fri":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sat":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sun":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM"},"photo":"https://framerusercontent.com/images/FZZB2fFlZNw7ZBUUtWI1Mwh0.png","poiId":"poi-spain-barcelona-fismuler"},{"id":"born-bar-brutal","name":"Bar Brutal","coordinates":[41.3849,2.1811],"description":"Bar Brutal is included for its natural-wine importance and continued social proof across editorial guides and geo-tagged dining posts. It is best for curious drinkers who want dinner to revolve around low-intervention bottles, lively service, and snackable plates, with the understanding that the wine culture is the main reason to go.","price":"$$","priceSource":"The Infatuation / Instagram","hours":{"mon":"7:00 PM-12:00 AM","tue":"7:00 PM-12:00 AM","wed":"7:00 PM-12:00 AM","thu":"7:00 PM-12:00 AM","fri":"1:00 PM-4:00 PM, 7:00 PM-12:30 AM","sat":"1:00 PM-4:00 PM, 7:00 PM-12:30 AM","sun":"1:00 PM-4:00 PM, 7:00 PM-12:00 AM"},"photo":"http://barbrutal.com/cdn/shop/files/Brutal_Trial_Websize_1600x1067.jpg?v=1770045996","poiId":"poi-spain-barcelona-bar-brutal"},{"id":"born-cuines-santa-caterina","name":"Cuines Santa Caterina","coordinates":[41.3867,2.1788],"description":"Cuines Santa Caterina is the practical market-adjacent anchor in El Born: sources and review volume point to it as reliable rather than rare. Under the Santa Caterina market roof, it covers rice, noodles, grilled dishes, and broad all-day hours, making it useful for groups, mixed appetites, and days when fixed Spanish meal times are inconvenient.","price":"$$","priceSource":"The Infatuation / Google Maps","hours":{"mon":"12:00 PM-12:00 AM","tue":"12:00 PM-12:00 AM","wed":"12:00 PM-12:00 AM","thu":"12:00 PM-12:00 AM","fri":"12:00 PM-1:00 AM","sat":"12:00 PM-1:00 AM","sun":"12:00 PM-12:00 AM"},"photo":"https://966e7448.delivery.rocketcdn.me/wp-content/uploads/thumb-CUINES-DE-SANTA-CATERINA.jpg","poiId":"poi-spain-barcelona-cuines-santa-caterina"},{"id":"born-el-xampanyet-restaurant","name":"El Xampanyet","coordinates":[41.3847,2.1836],"description":"El Xampanyet is one of the clearest source-backed Born classics, with editorial guides and traveler reviews agreeing on the same strengths: cava, anchovies, conservas, simple tapas, and a room that is almost always crowded. Treat it as a short, loud, salty stop near the Picasso Museum rather than a slow sit-down dinner.","price":"$","priceSource":"The Infatuation / Tripadvisor","hours":{"mon":"7:00 PM-11:00 PM","tue":"12:00 PM-3:30 PM, 7:00 PM-11:00 PM","wed":"12:00 PM-3:30 PM, 7:00 PM-11:00 PM","thu":"12:00 PM-3:30 PM, 7:00 PM-11:00 PM","fri":"12:00 PM-3:30 PM, 7:00 PM-11:00 PM","sat":"12:00 PM-3:30 PM","sun":"Closed"},"photo":"https://www.elxampanyet.com/wp-content/uploads/2024/10/Iriarte_0132-2048x1353.jpg","poiId":"poi-spain-barcelona-el-xampanyet"}],"sources":[{"name":"The Infatuation - El Born","url":"https://www.theinfatuation.com/barcelona/neighborhoods/el-born"},{"name":"The Infatuation - Best Restaurants in Barcelona","url":"https://www.theinfatuation.com/barcelona/guides/best-restaurants-hotels-barcelona"},{"name":"Eater - Old City restaurants","url":"https://www.eater.com/maps/barcelona-old-city-gothic-quarter-best-restaurants"},{"name":"Time Out - Barcelona restaurants","url":"https://www.timeout.com/barcelona/restaurants"},{"name":"Tripadvisor - Barcelona restaurants","url":"https://www.tripadvisor.com/Restaurants-g187497-Barcelona_Catalonia.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-barcelona-eixample-restaurants', 'barcelona-eixample-restaurants', 'Food', 'Spain', 'Barcelona', 'Eixample', '{"id":"list-barcelona-eixample-restaurants","slug":"barcelona-eixample-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Eixample, Barcelona","seoDescription":"Best restaurants in Eixample, Barcelona, from destination tasting menus and polished tapas counters to design-hotel dining rooms and reliable group-friendly classics.","title":"Big-Deal Tables and Tapas","description":"Eixample is where polished meals fit naturally into architecture days: tasting-menu reservations, hotel-linked natural wine, tapas counters, and group-friendly rooms that make sense around Passeig de Gracia and the grid.","url":"https://www.google.com/maps/search/eixample+restaurants+barcelona","category":"Food","location":{"city":"Barcelona","neighborhood":"Eixample","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-04-29T00:00:00.000Z","stops":[{"id":"eixample-disfrutar","name":"Disfrutar","coordinates":[41.3878,2.1533],"description":"Disfrutar is the global destination restaurant in this data set, supported by MICHELIN''s top recognition and World''s 50 Best placement. The elBulli-alumni kitchen is known for highly technical, playful tasting menus, so it belongs in the expensive filter and should be framed as a trip-defining reservation rather than a neighborhood dinner.","price":"$$$","priceSource":"MICHELIN Guide / World''s 50 Best","hours":{"mon":"Closed","tue":"1:00 PM-2:15 PM, 8:00 PM-9:15 PM","wed":"1:00 PM-2:15 PM, 8:00 PM-9:15 PM","thu":"1:00 PM-2:15 PM, 8:00 PM-9:15 PM","fri":"1:00 PM-2:15 PM, 8:00 PM-9:15 PM","sat":"1:00 PM-2:15 PM, 8:00 PM-9:15 PM","sun":"Closed"},"photo":"https://www.disfrutarbarcelona.com/api/uploads/restaurant/images/original/0c171d8288ac922fcd372beaceccb58d_phpQfnqi9.jpg","poiId":"poi-spain-barcelona-disfrutar"},{"id":"eixample-bar-mut-restaurant","name":"Bar Mut","coordinates":[41.3917,2.1554],"description":"Bar Mut is a polished Eixample bistro pick with strong guide and map signals around wine, seasonal Catalan plates, and late lunch-to-dinner demand near Passeig de Gràcia. It is pricier than a casual tapas bar, but useful when travelers want a classic Barcelona room that still feels compact and food-focused.","price":"$$$","priceSource":"The Infatuation / Google Maps","hours":{"mon":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","tue":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","wed":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","thu":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","fri":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sat":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sun":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM"},"photo":"https://api.nnhotels.com/storage/171219/5a58ce53eca45bad3b1b015a/xl/bar-mut-pau-claris-192-2jpg-1.jpg","poiId":"poi-spain-barcelona-bar-mut"},{"id":"eixample-bodega-bonay","name":"Bodega Bonay","coordinates":[41.3918,2.1746],"description":"Bodega Bonay is included because The Infatuation and reservation signals position it as one of Eixample''s better hotel-linked dining rooms. The draw is Casa Bonay''s design ecosystem: natural wine, anchovies, cecina, pastas, and long lunches that feel stylish without requiring a tasting menu.","price":"$$","priceSource":"The Infatuation / Resy","hours":{"mon":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","tue":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","wed":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","thu":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","fri":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sat":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sun":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM"},"photo":"https://cdn-hhbfohb.nitrocdn.com/MWVuFFQrOubRCgucqTrIdzQgXRECTcge/assets/images/optimized/rev-41ae578/casabonay.com/wp-content/uploads/2020/12/ATP9564@antp-900x1196.jpg","poiId":"poi-spain-barcelona-bodega-bonay"},{"id":"eixample-paco-meralgo","name":"Paco Meralgo","coordinates":[41.3915,2.1519],"description":"Paco Meralgo is the reliable mid-range tapas counter for Eixample, backed more by review volume and practical usefulness than by novelty. It works when diners want croquettes, bombas, seafood, and quick service in a polished room, especially when higher-profile reservations are unavailable.","price":"$$","priceSource":"Google Maps / Tripadvisor","hours":{"mon":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","tue":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","wed":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","thu":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","fri":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sat":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sun":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM"},"photo":"https://restaurantpacomeralgo.com/wp-content/uploads/2024/05/paco4.jpg","poiId":"poi-spain-barcelona-paco-meralgo"},{"id":"eixample-cerveceria-catalana","name":"Cervecería Catalana","coordinates":[41.3921,2.1602],"description":"Cervecería Catalana remains on the list because Google Maps and Tripadvisor volume confirm its role as a high-demand tapas machine. It is not hidden, but it is consistent: fast counter service, montaditos, seafood, tortillas, and a wait that is often part of the experience rather than a sign to abandon the plan.","price":"$$","priceSource":"Google Maps / Tripadvisor","hours":{"mon":"12:00 PM-12:00 AM","tue":"12:00 PM-12:00 AM","wed":"12:00 PM-12:00 AM","thu":"12:00 PM-12:00 AM","fri":"12:00 PM-1:00 AM","sat":"12:00 PM-1:00 AM","sun":"12:00 PM-12:00 AM"},"photo":"https://static.wixstatic.com/media/fae8fc_8b397159d3774db6b2f37b7e4299dd2f%7Emv2.png/v1/fit/w_2500,h_1330,al_c/fae8fc_8b397159d3774db6b2f37b7e4299dd2f%7Emv2.png","poiId":"poi-spain-barcelona-cerveceria-catalana"},{"id":"eixample-el-nacional-restaurant","name":"El Nacional","coordinates":[41.3917,2.168],"description":"El Nacional is best understood as a logistics and atmosphere pick rather than a critic''s secret. Time Out and map data support it as a central, visually memorable food hall with separate counters for meat, seafood, tapas, and drinks, making it especially useful for groups near Passeig de Gràcia.","price":"$$","priceSource":"Time Out / Google Maps","hours":{"mon":"12:00 PM-12:00 AM","tue":"12:00 PM-12:00 AM","wed":"12:00 PM-12:00 AM","thu":"12:00 PM-12:00 AM","fri":"12:00 PM-1:00 AM","sat":"12:00 PM-1:00 AM","sun":"12:00 PM-12:00 AM"},"photo":"https://www.elnacionalbcn.com/wp-content/uploads/2023/03/La-Parada.webp","poiId":"poi-spain-barcelona-el-nacional"}],"sources":[{"name":"The Infatuation - Best Restaurants in Eixample","url":"https://www.theinfatuation.com/barcelona/guides/best-restaurants-eixample"},{"name":"The Infatuation - Best Restaurants in Barcelona","url":"https://www.theinfatuation.com/barcelona/guides/best-restaurants-hotels-barcelona"},{"name":"Eater - Best Restaurants in Barcelona","url":"https://www.eater.com/maps/best-restaurants-barcelona-spain"},{"name":"MICHELIN Guide - Disfrutar","url":"https://guide.michelin.com/us/en/catalunya/barcelona/restaurant/disfrutar"},{"name":"World''s 50 Best - Disfrutar","url":"https://www.theworlds50best.com/discovery/Establishments/Spain/Barcelona/Disfrutar.html"},{"name":"Time Out - Best restaurants in Barcelona","url":"https://www.timeout.com/barcelona/restaurants/best-restaurants-in-barcelona"},{"name":"Tripadvisor - Barcelona restaurants","url":"https://www.tripadvisor.com/Restaurants-g187497-Barcelona_Catalonia.html